-- ============================================================
-- SEED: Essential SAT Vocabulary (200 words)
-- Run AFTER migration-vocabulary.sql
-- ============================================================

ON CONFLICT DO NOTHING;

-- Get the list id we just inserted (or already had)
DO $$
DECLARE
  list_id_var BIGINT;
BEGIN
  SELECT id INTO list_id_var FROM public.vocab_lists WHERE title = 'Essential SAT 200' LIMIT 1;

  -- Only seed if the list is empty
  IF NOT EXISTS (SELECT 1 FROM public.vocab_words WHERE list_id = list_id_var) THEN
  END IF;
END $$;
